function validateMission(value) {
  assertPlainObject(value, "mission");
  validateMissionId(value.id);
  if (!Number.isSafeInteger(value.sequence) || value.sequence < 1) fail("MALFORMED_MANIFEST", "mission sequence is invalid");
  validateRunId(value.runId, { native: value.dispatch?.kind === "native-trial" });
  validateSessionId(value.sessionId);
  assertSafeText(value.title, "mission title", 64);
  assertSafeText(value.substrate, "mission substrate", 32);
  if (value.paneId !== null && (typeof value.paneId !== "string" || !/^%\d+$/u.test(value.paneId))) {
    fail("MALFORMED_MANIFEST", "mission pane id is invalid");
  }
  // panePid binds the pane's process identity at spawn time; pane markers
  // survive respawn-pane, so the pid is the only evidence that the marked
  // pane still runs the mission's own wrapper. Optional: legacy rows lack it.
  if (value.panePid !== undefined && value.panePid !== null
    && (!Number.isSafeInteger(value.panePid) || value.panePid < 1)) {
    fail("MALFORMED_MANIFEST", "mission pane pid is invalid");
  }
  if (typeof value.cwd !== "string" || !path.isAbsolute(value.cwd) || value.cwd.includes("\0")) {
    fail("MALFORMED_MANIFEST", "mission cwd must be absolute");
  }
  if (value.status !== "starting" && value.status !== "running" && value.status !== "completed" && value.status !== "stopped") {
    fail("MALFORMED_MANIFEST", "mission status is invalid");
  }
  if (value.runnerReservation === undefined) {
    value.runnerReservation = value.status === "completed" ? 0 : 1;
  } else if (!Number.isSafeInteger(value.runnerReservation) || value.runnerReservation < 0) {
    fail("MALFORMED_MANIFEST", "mission runner reservation is invalid");
  } else if (value.status !== "completed" && value.runnerReservation < 1) {
    fail("MALFORMED_MANIFEST", "active mission runner reservation must be positive");
  }
  if (value.status === "completed") {
    if (typeof value.completedAt !== "string" || Number.isNaN(Date.parse(value.completedAt))) {
      fail("MALFORMED_MANIFEST", "completed mission must have a valid completedAt timestamp");
    }
    if (value.finalNote !== null && value.finalNote !== undefined && typeof value.finalNote !== "string") {
      fail("MALFORMED_MANIFEST", "finalNote must be a string");
    }
    if (value.completedCapture !== undefined && value.completedCapture !== null && typeof value.completedCapture !== "string") {
      fail("MALFORMED_MANIFEST", "completedCapture must be a string");
    }
  }
  if (value.status === "stopped") {
    if (typeof value.stoppedAt !== "string" || Number.isNaN(Date.parse(value.stoppedAt))) {
      fail("MALFORMED_MANIFEST", "stopped mission must have a valid stoppedAt timestamp");
    }
    // Normalize absent outcome fields to null so the late-stop backfill in
    // stopMission (which keys on === null) also covers legacy rows.
    if (value.exitCode === undefined) value.exitCode = null;
    if (value.exitSignal === undefined) value.exitSignal = null;
    if (value.exitCode !== null && !Number.isSafeInteger(value.exitCode)) {
      fail("MALFORMED_MANIFEST", "stopped exitCode must be an integer or null");
    }
    if (value.exitSignal !== null && (typeof value.exitSignal !== "string" || value.exitSignal.includes("\0"))) {
      fail("MALFORMED_MANIFEST", "stopped exitSignal must be a string or null");
    }
  }
  // S-10: relay is an operator-supplied display label, not an authenticated
  // origin. It marks missions dispatched from the operator surface (L0) but
  // carries no cryptographic attestation. Downstream consumers MUST NOT treat
  // it as a security boundary or authorization token.
  if (value.relay !== undefined && typeof value.relay !== "boolean") fail("MALFORMED_MANIFEST", "mission relay flag must be a boolean");
  if (value.fleet == null || value.fleet === "") {
    value.fleet = null;
  } else if (typeof value.fleet !== "string" || !FLEET_NAME_PATTERN.test(value.fleet)) {
    fail("MALFORMED_MANIFEST", "mission fleet is invalid");
  }
